<script setup lang="ts">
import { computed,onMounted,reactive,ref,watch } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessageBox, ElDialog, ElSelect, ElOption, ElInputNumber } from 'element-plus'
import type { FormInstance,FormRules } from 'element-plus'
import PlatformLayout from '../components/PlatformLayout.vue'
import { useApi,type Row } from '../composables/useApi'
const route=useRoute(),{api,act}=useApi(),rows=ref<Row[]>([]),loading=ref(false),saving=ref(false),error=ref(''),open=ref(false),editing=ref(''),formRef=ref<FormInstance>()
const pets=computed(()=>route.path==='/pets'),title=computed(()=>pets.value?'宠物档案':'上门地址')
const form=reactive({name:'',notes:'',species:'CAT',breed:'',ageMonths:0,contact:'',phone:'',region:'',detail:''})
const rules:FormRules={name:[{required:true,whitespace:true,message:'请输入宠物名字'}],contact:[{required:true,whitespace:true,message:'请输入联系人'}],phone:[{required:true,message:'请输入电话'},{pattern:/^[0-9+ -]{7,20}$/,message:'请输入有效联系电话'}],region:[{required:true,whitespace:true,message:'请输入服务区域'}],detail:[{required:true,whitespace:true,message:'请输入详细地址'}]}
async function load(){loading.value=true;error.value='';try{rows.value=await api<Row[]>(pets.value?'/pets':'/addresses')}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
function edit(row?:Row){editing.value=row?.ID??'';Object.assign(form,{name:row?.NAME??'',notes:row?.NOTES??'',species:row?.SPECIES??'CAT',breed:row?.BREED??'',ageMonths:row?.AGE_MONTHS??0,contact:row?.CONTACT??'',phone:row?.PHONE??'',region:row?.REGION??'',detail:row?.DETAIL??''});open.value=true}
async function save(){if(saving.value||!await formRef.value?.validate().catch(()=>false))return;saving.value=true;const path=pets.value?(editing.value?`/pets/${editing.value}`:'/pet-profiles'):(editing.value?`/addresses/${editing.value}`:'/addresses');const body=pets.value?{name:form.name.trim(),notes:form.notes,species:form.species,breed:form.breed,ageMonths:form.ageMonths}:{contact:form.contact.trim(),phone:form.phone,region:form.region.trim(),detail:form.detail.trim()};if(await act(()=>api(path,editing.value?'PUT':'POST',body),'保存成功')){open.value=false;await load()}saving.value=false}
async function remove(row:Row){try{await ElMessageBox.confirm('删除后将不能用于新预约，历史订单保留原资料快照。','确认删除',{type:'warning'});if(await act(()=>api(`${pets.value?'/pets':'/addresses'}/${row.ID}`,'DELETE'),'已删除'))await load()}catch{/* 用户取消 */}}
watch(()=>route.path,()=>{open.value=false;load()});onMounted(load)
</script>
<template><PlatformLayout><div class="page-heading"><div><span class="eyebrow">CARE DETAILS</span><h1>{{ title }}</h1><p>{{ pets?'记录毛孩子的习惯，让每次照顾更细心。':'填写准确的服务区域、联系方式与门牌地址。' }}</p></div><el-button type="primary" @click="edit()">{{ pets?'添加宠物':'添加地址' }}</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><div v-loading="loading" class="business-card"><el-empty v-if="!rows.length" :description="`还没有${title}，点击右上角添加。`"/><div v-else class="profile-grid"><article v-for="row in rows" :key="row.ID" class="profile-card"><span class="profile-avatar">{{ pets?(row.SPECIES==='DOG'?'🐕':'🐈'):'⌂' }}</span><h3>{{ pets?row.NAME:row.CONTACT }}</h3><p>{{ pets?`${row.SPECIES==='CAT'?'猫':row.SPECIES==='DOG'?'狗':'其他宠物'} · ${row.BREED||'未填写品种'} · ${row.AGE_MONTHS} 个月`:row.PHONE }}</p><p v-if="pets" class="long-text">{{ row.NOTES||'暂无特别注意事项' }}</p><template v-else><p class="long-text">服务区域：{{ row.REGION }}</p><p class="long-text">详细地址：{{ row.DETAIL }}</p></template><div class="card-actions"><el-button @click="edit(row)">编辑</el-button><el-button text type="danger" @click="remove(row)">删除</el-button></div></article></div></div>
<el-dialog v-model="open" :title="`${editing?'编辑':'添加'}${pets?'宠物':'地址'}`" width="min(520px, 92vw)" destroy-on-close :close-on-click-modal="!saving"><el-form ref="formRef" :model="form" :rules="rules" label-position="top" @submit.prevent="save"><template v-if="pets"><el-form-item label="宠物名字" prop="name"><el-input v-model="form.name" maxlength="80"/></el-form-item><div class="form-two"><el-form-item label="宠物类型"><el-select v-model="form.species"><el-option label="猫" value="CAT"/><el-option label="狗" value="DOG"/><el-option label="其他" value="OTHER"/></el-select></el-form-item><el-form-item label="年龄（月）"><el-input-number v-model="form.ageMonths" :min="0" :max="600"/></el-form-item></div><el-form-item label="品种"><el-input v-model="form.breed" maxlength="80"/></el-form-item><el-form-item label="喂养习惯与注意事项"><el-input v-model="form.notes" type="textarea" :rows="4" maxlength="1000" show-word-limit placeholder="例如：每天一勺猫粮，需要换水，不要开窗。"/></el-form-item></template><template v-else><el-form-item label="联系人" prop="contact"><el-input v-model="form.contact" maxlength="40"/></el-form-item><el-form-item label="联系电话" prop="phone"><el-input v-model="form.phone" maxlength="20"/></el-form-item><el-form-item label="服务区域" prop="region"><el-input v-model="form.region" maxlength="80" placeholder="上门位置所在区域，例如：武汉市洪山区"/></el-form-item><el-form-item label="详细地址" prop="detail"><el-input v-model="form.detail" type="textarea" :rows="3" maxlength="200" placeholder="街道、小区、楼栋及门牌号"/></el-form-item></template><el-button type="primary" native-type="submit" :loading="saving">保存</el-button></el-form></el-dialog></PlatformLayout></template>
